struct AsyncAwaitExampleView: View {
    @State private var joke = "Lade Witz..."

    var body: some View {
        VStack(spacing: 20) {
            Text(joke)
                .multilineTextAlignment(.center)
                .padding()

            Button("Neuen Witz laden") {
                Task { await loadJoke() }
            }
            .buttonStyle(.borderedProminent)
        }
        .padding()
    }

    func loadJoke() async {
        guard let url = URL(string: "https:/official-joke-api.appspot.com/random_joke") else { return }
        do {
            let (data, _) = try await URLSession.shared.data(from: url)
            if let decoded = try? JSONDecoder().decode(Joke.self, from: data) {
                joke = "\(decoded.setup)\n\n💬 \(decoded.punchline)"
            }
        } catch {
            joke = "Fehler beim Laden 😅"
        }
    }
}

